<script setup lang="ts">
import {useTableWidths as useListTableWidths} from './tableWidths'
const listWidths=useListTableWidths('ShipmentDocumentDialogLists')

import {ref,reactive,watch} from 'vue'
import {api} from './session'
import {ElMessage} from 'element-plus'
const props=defineProps<{target:any}>(),emit=defineEmits(['close','saved'])
const templates=ref<any[]>([]),templateId=ref<number>(),context=ref<any>(),values=reactive<Record<string,string>>({}),busy=ref(false),error=ref(''),labels=ref<any>({}),columns=ref<any>({})
watch(()=>props.target,async t=>{if(!t)return;templateId.value=undefined;context.value=null;error.value='';Object.keys(values).forEach(k=>delete values[k]);try{templates.value=(await api('/logistics/templates?kind='+t.kind)).filter((x:any)=>x.mapping?.sheet);context.value=await api('/logistics/shipment?'+new URLSearchParams({store:t.store,shipment_id:t.shipment_id,kind:t.kind}));}catch(e){error.value=(e as Error).message}},{immediate:true})
watch(templateId,async id=>{if(!id)return;try{const d=await api(`/logistics/templates/${id}/preview`);labels.value=d.scalars;columns.value=d.columns;const t=templates.value.find(t=>t.id===id);for(const k of Object.keys(t.mapping.fields))values[k]=String(context.value[k]??(k==='supplier'?t.supplier:''))}catch(e){error.value=(e as Error).message}})
function mapped(){return templates.value.find(t=>t.id===templateId.value)?.mapping||{fields:{},columns:{}}}
async function generate(){busy.value=true;error.value='';try{await api('/logistics/documents',{store:props.target.store,shipment_id:props.target.shipment_id,template_id:templateId.value,values,items:context.value.items});emit('saved');emit('close');ElMessage.success('已生成，可在对应单据页下载')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><el-dialog :model-value="!!target" :title="target?.kind==='invoice'?'生成清关发票':'生成报关单'" width="min(1200px,96vw)" @close="emit('close')"><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-select v-model="templateId" placeholder="选择已配置的模板" style="width:420px"><el-option v-for="t in templates" :key="t.id" :value="t.id" :label="`${t.name} · ${t.supplier||'通用'}`"/></el-select><p v-if="!templates.length">请先到物流中心上传模板并配置字段。</p><template v-if="templateId&&context"><el-form label-position="top" style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:18px"><el-form-item v-for="(_,key) in mapped().fields" :key="key" :label="labels[key]"><el-select v-if="key==='currency'" v-model="values[key]"><el-option v-for="(label,value) in {CNY:'人民币',EUR:'欧元',GBP:'英镑'}" :value="value" :label="label"/></el-select><el-input v-else v-model="values[key]" :disabled="['shipment_id','store','weight','boxes','total'].includes(String(key))"/></el-form-item></el-form><template v-if="true"><TableReset table-key="ShipmentDocumentDialogLists/list-1"/><el-table data-width-key="ShipmentDocumentDialogLists/list-1" @header-dragend="(w:number,_:number,c:any)=>listWidths.resize('list-1',w,c)" @header-contextmenu="(c:any,e:MouseEvent)=>listWidths.resetColumn('list-1',c,e)" :data="context.items" border><el-table-column :column-key="'sku'" :width="listWidths.width('list-1','sku',undefined)" prop="sku" label="SKU" min-width="180"/><el-table-column :column-key="'quantity'" :width="listWidths.width('list-1','quantity','90')" prop="quantity" label="数量" /><el-table-column :column-key="key" :width="listWidths.width('list-1',key,undefined)" v-for="key in Object.keys(mapped().columns).filter(k=>!['sku','quantity'].includes(k))" :key="key" :label="columns[key]" min-width="160"><template #default="{row}"><span v-if="['fnsku','code'].includes(key)">{{row[key]}}</span><span v-else-if="key==='amount'">{{row.unit_price==null?'—':(Number(row.unit_price)*row.quantity).toFixed(2)}}</span><el-input-number v-else-if="['unit_price','weight','tax_rate'].includes(key)" v-model="row[key]" :min="0" :precision="4" :controls="false" style="width:130px"/><el-select v-else-if="key==='currency'" v-model="row[key]"><el-option v-for="(label,value) in {CNY:'人民币',EUR:'欧元',GBP:'英镑'}" :value="value" :label="label"/></el-select><el-input v-else v-model="row[key]"/></template></el-table-column><el-table-column :column-key="'column-4'" :width="listWidths.width('list-1','column-4','160')" v-if="!mapped().columns.unit_price&&(mapped().columns.amount||mapped().fields.total)" label="申报单价" ><template #default="{row}"><el-input-number v-model="row.unit_price" :min="0" :precision="4" :controls="false" style="width:130px"/></template></el-table-column></el-table></template></template><template #footer><el-button @click="emit('close')">取消</el-button><el-button type="primary" :disabled="!templateId||!context" :loading="busy" @click="generate">生成 Excel</el-button></template></el-dialog></template>
